import { Item as RadixItem } from '@radix-ui/react-dropdown-menu';
import React, { forwardRef, useState } from 'react';

import { getItemSlots } from './item-slots.js';
import { StyledMenuItem } from './ItemStyles.js';
import { MenuItemTooltipWrapper } from './ItemTooltip.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { _useTooltipState } from '../../overlays/hooks/useTooltipState.js';

/** Props for the Menu.Link component */
export interface MenuLinkOwnProps extends WithChildren, AriaLabelingProps {
  /**
   * Whether the menu link is disabled.
   * If `true`, it prevents the user from interacting with the link and the link
   * being focused.
   */
  disabled?: boolean;
  /**
   * Optional text used for typeahead purposes. By default, the typeahead
   * behavior will use the `.textContent` of the link. Use this when the content
   * is complex, or you have non-textual content inside.
   */
  textValue?: string;
}

export type MenuLinkProps<E extends React.ElementType> =
  PolymorphicComponentProps<E, MenuLinkOwnProps>;

/**
 * The component that contains the dropdown menu Links.
 */
export const Link: <E extends React.ElementType = 'a'>(
  props: MenuLinkProps<E>,
) => React.ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends React.ElementType>(
    {
      children,
      disabled = false,
      as,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
      ...remainingProps
    }: MenuLinkProps<E>,
    forwardedRef: typeof remainingProps.ref,
  ) => {
    const slots = getItemSlots(children);

    const {
      isOpen,
      open: openTooltip,
      close: closeTooltip,
    } = _useTooltipState({
      defaultOpen: false,
    });

    const [tooltipTriggerRef, setTooltipTriggerRef] =
      useState<HTMLElement | null>(null);

    const { focusProps, focusStyles, isFocusVisible } = useFocusRing();

    return (
      <>
        <RadixItem
          ref={forwardedRef}
          {..._mergeProps(focusProps, {
            onFocus: () => slots.tooltip && !disabled && openTooltip(true),
            onBlur: () => slots.tooltip && !disabled && closeTooltip(true),
          })}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          aria-describedby={ariaDescribedBy}
          aria-details={ariaDetails}
          role="menuitem"
          asChild
        >
          <StyledMenuItem
            {...remainingProps}
            $focusStyle={focusStyles}
            $isFocusVisible={isFocusVisible}
            as={as !== undefined ? as : 'a'}
            ref={setTooltipTriggerRef}
            disabled={disabled}
            aria-disabled={disabled}
          >
            {slots.icon}
            <div className="item-children">{slots.freeform}</div>
          </StyledMenuItem>
        </RadixItem>
        {isOpen === true && (
          <MenuItemTooltipWrapper triggerElement={tooltipTriggerRef}>
            {slots.tooltip}
          </MenuItemTooltipWrapper>
        )}
      </>
    );
  },
);

(Link as typeof Link & { displayName: string }).displayName = 'Menu.Link';
